local zones = {
	[947] = {
		name = "Azeroth",
		short = "Hace diez mil años, los Altonato de Kalimdor, ebrios del poder del Pozo de la Eternidad, respondieron a la llamada del titán caído Sargeras y abrieron un portal para la Legión Ardiente.",
		full = "Hace diez mil años, los Altonato de Kalimdor, ebrios del poder del Pozo de la Eternidad, respondieron a la llamada del titán caído Sargeras y abrieron un portal para la Legión Ardiente. Malfurion Tempestira y la resistencia kaldorei destruyeron ese portal con el Alma de Dragón y arrojaron a Sargeras de vuelta al Vacío Abismal, pero el derrumbe del Pozo quebró el mundo entero. La antigua Kalimdor se hundió entre fuego e inundaciones; de los restos surgieron continentes en ruinas, y el corazón anegado de aquella tierra se convirtió en el Gran Mar, con la Vorágine agitándose allí donde antaño se alzaba el Pozo.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar es una tierra roja y agrietada de riscos y cañones, seca y calurosa, escasa en agua y en verdor.",
		full = "Durotar es una tierra roja y agrietada de riscos y cañones, seca y calurosa, escasa en agua y en verdor. Los orcos encuentran en ella una belleza áspera que les recuerda a Draenor, y fue aquí, tras el Monte Hyjal, donde Thrall condujo a su pueblo para levantar un nuevo hogar, al que dio el nombre de su padre asesinado, Durotan. La tierra había pertenecido a los jabaespines Crines de Acero hasta que la Horda los expulsó.\n\nAquella paz no duró mucho. El almirante general Daelin Valiente, héroe de la Segunda Guerra y ningún amigo de los orcos, lanzó una gran flota de la Alianza contra Durotar, decidido a aplastar a la Horda antes de que echara raíces. Su hija Jaina eligió otro camino: en Theramore se volvió contra su propio padre para luchar junto a Thrall, y Daelin murió en la batalla sin que ambos pudieran reconciliarse jamás. En agradecimiento por su lealtad, Thrall permitió que los soldados de Jaina se retiraran ilesos a Theramore.\n\nLos trols Lanza Negra llegaron a la costa de Durotar como exiliados, no como colonos por voluntad propia. Traicionados por uno de los suyos, el hechicero Zalazane, fueron expulsados de su hogar en las Islas del Eco y levantaron la aldea pesquera de Sen'jin en la orilla del continente, sin poder recuperar jamás lo que Zalazane les había arrebatado.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "Durante cientos de años, los tauren no tuvieron tierra propia, empujados de un extremo a otro de Kalimdor por los asaltantes centauros, que dispersaron sus tribus en campamentos errantes.",
		full = "Durante cientos de años, los tauren no tuvieron tierra propia, empujados de un extremo a otro de Kalimdor por los asaltantes centauros, que dispersaron sus tribus en campamentos errantes. Cuando Thrall y sus orcos desembarcaron en estas costas, Cairne Pezuña de Sangre los contempló y vio en ellos espíritus afines, honorables y fuertes. Con la escolta de los orcos y su fuerza respaldándolo, Cairne guio a su pueblo hasta el valle resguardado, cercado de montañas por todos lados, y allí su tribu Pezuña de Sangre expulsó a los centauros de las praderas y las reclamó por fin.\n\nSobre la meseta que se alzaba por encima de la llanura, Cairne construyó Cima del Trueno, un refugio abierto a los tauren de todas las tribus, y con el tiempo los pueblos dispersos se unieron bajo su mando.\n\nLos pastos siguen verdes, las mesetas aún proyectan sus largas sombras sobre el Poblado Pezuña de Sangre, y todo tauren que alcanza la madurez debe adentrarse todavía en las llanuras salvajes para demostrar su valía en la Gran Cacería, como hicieron sus ancestros.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "Los Baldíos",
		short = "El polvo de este lugar no siempre fue polvo. Antaño esto era un bosque, cuidado por los kaldorei que levantaron la avanzada de Then'Ralore, y se dice que el semidiós Lo'Gosh se enfrentó aquí a la Legión Ardiente durante la Guerra de los Ancestros.",
		full = "El polvo de este lugar no siempre fue polvo. Antaño esto era un bosque, cuidado por los kaldorei que levantaron la avanzada de Then'Ralore, y se dice que el semidiós Lo'Gosh se enfrentó aquí a la Legión Ardiente durante la Guerra de los Ancestros. El Gran Diluvio puso fin a todo aquello, y el verde valle se convirtió en la llanura abrasada por el sol que es hoy.\n\nDurante generaciones, los tauren recorrieron estas llanuras cazando kodos y truenagartos, buscando la sabiduría de la Madre Tierra, siempre acosados por los centauros, que los cazaban por diversión. Se defendían, pero nunca por amor a la guerra; cuando llegaban los hombres caballo, desmontaban sus tiendas y se marchaban antes que desperdiciar vidas. Un año de paz, un año de guerra: así era la vida de los tauren, hasta que los orcos de Thrall y los trols Lanza Negra desembarcaron y marcharon junto a los tauren Pezuña de Sangre contra los centauros. Tras la caída de la Legión en el Monte Hyjal, Thrall reclamó los Baldíos orientales, expulsó a los jabaespines Crines de Acero y llamó a esa tierra Durotar, erigiendo Orgrimmar como su capital.\n\nLa tierra guarda también penas más antiguas: se dice que un hombre llamado Dethorin encontró a su amada Allurana en brazos de otro, y que su grito arrancó de la arena el hacha Killmaim, la misma hoja con la que la mató.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "Después de que el Diluvio quebrara el mundo, los elfos de la noche que quedaron se apartaron deliberadamente del resto del mundo.",
		full = "Después de que el Diluvio quebrara el mundo, los elfos de la noche que quedaron se apartaron deliberadamente del resto del mundo. Entre los humanos, Kalimdor sobrevivió solo como leyenda, una tierra que, según se decía, se había partido y hundido bajo las olas, sin que conocieran su ubicación ni su forma.\n\nPero no se había perdido del todo. Los elfos de la noche visitaron a los quel'dorei en los años siguientes, y así solo los altos elfos de Quel'Thalas sabían que la leyenda era cierta.\n\nIncluso cuando llegó la Tercera Guerra, la mayoría de los humanos seguía negándose a creer que Kalimdor existiera, y el propio embajador del Kirin Tor en la corte del rey Terenas se contaba entre los escépticos. Solo unos pocos atendieron la advertencia de Medivh y zarparon hacia el oeste, entre ellos la nueva Horda de Thrall, seguida de la expedición de Jaina Valiente. Lo que encontraron no fue una leyenda, sino todo un continente, con hielo en el norte, desierto en el sur y elfos de la noche que aún defendían los bosques entre ambos.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Reinos del Este",
		short = "Los Reinos del Este no siempre fueron muchas tierras.",
		full = "Los Reinos del Este no siempre fueron muchas tierras. Antaño formaban parte de un único continente, antes de que el Gran Diluvio desgarrara el mundo y dejara atrás los fragmentos rotos que hoy se llaman Azeroth, Khaz Modan y Lordaeron, con Quel'Thalas aferrada al norte de esta última tierra destrozada, sin saber aún hoy si es un lugar por derecho propio o apenas un rincón de otro.\n\nA lo largo de estos fragmentos, las montañas de Khaz Modan y Crestagrana se alzan como una columna vertebral a través del corazón del continente, y a su alrededor perduran los pueblos antiguos: enanos y gnomos en sus salones profundos, humanos en sus reinos, altos elfos en sus bosques, y ahora los Renegados, alzados allí donde antes vivía el pueblo de Lordaeron. Orcos, goblins, nagas y ogros también han llegado a estas tierras, aunque ninguno de ellos nació en ellas.\n\nLas cicatrices de aquella primera ruptura siguen siendo la verdad de este lugar. Cada frontera, cada estrecho y cada extensión de tierra anegada entre un reino y el siguiente recuerda que los Reinos del Este fueron una vez un todo, y que ya no lo son.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Montañas de Alterac",
		short = "La lluvia nunca deja del todo de caer sobre estas cumbres, y el cielo que las cubre es siempre gris. Antaño, las montañas coronaban la ciudad-estado de Alterac, que dominaba gran parte de las tierras del norte, y además daban cobijo a Dalaran.",
		full = "La lluvia nunca deja del todo de caer sobre estas cumbres, y el cielo que las cubre es siempre gris. Antaño, las montañas coronaban la ciudad-estado de Alterac, que dominaba gran parte de las tierras del norte, y además daban cobijo a Dalaran. Ambas han desaparecido, y lo que queda explica por qué tan pocos se atreven a subir hasta aquí.\n\nAl terminar la Segunda Guerra, la Alianza de Lordaeron descubrió que los señores de Alterac habían pactado en secreto con la Horda, y envió un ejército a estas montañas para golpear a los traidores en su propio hogar. La ciudad cayó, su gente fue dispersada o encarcelada, y su linaje nunca recuperó el trono. Un príncipe posterior de aquella casa caída, Aliden Perenolde, se alzó en cambio como señor de bandidos y reunió a los proscritos y a los vengativos en la Hermandad, una compañía de pícaros que aún domina Strahnbrad y recorre estas laderas con la intención de recuperar lo que perdió su familia.\n\nHoy las ruinas de la Ciudad de Alterac pertenecen a los ogros Aplastacresta, y la Hermandad controla gran parte de lo que no es de los ogros.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Tierras Altas de Arathi",
		short = "El rey Thoradin llegó a esta tierra árida porque un sueño le dijo que su pueblo prosperaría aquí, y sobre ella levantó Strom, la primera capital de una Arathor unida.",
		full = "El rey Thoradin llegó a esta tierra árida porque un sueño le dijo que su pueblo prosperaría aquí, y sobre ella levantó Strom, la primera capital de una Arathor unida. El suelo seco le sirvió como un muro de espinas que negaba a los trols del bosque de Amani la cobertura para sus emboscadas, y además levantó un segundo muro. Durante mil años Strom se mantuvo en el corazón del imperio, hasta que sus casas nobles se marcharon hacia tierras más fértiles y los últimos descendientes de Thoradin partieron para fundar Ventormenta. Lo que quedó se convirtió en Stromgarde, gobernada desde entonces por el linaje Aterratrols.\n\nStromgarde ha caído desde entonces, arrasada por los ogros y la Hermandad, y sus supervivientes fueron expulsados de la fortaleza a un cañón que ahora llaman Refugio de la Zaga. Cerca se alza Sentencia, que antaño fue un campamento donde la humanidad encerraba a sus prisioneros orcos y que hoy está en manos de los propios orcos, rebautizada en honor a Orgrim Martillo Maldito.\n\nLa gran muralla de Thoradin se ha derrumbado hasta quedar convertida en una ruina abierta, y su fortaleza yace destrozada y disputada, aún objeto de lucha entre los ogros, la Hermandad y los últimos soldados de un reino que intenta recuperarla.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Tierras Inhóspitas",
		short = "Las Tierras Inhóspitas son un desierto agrietado de tierra seca, rocas dispersas y cañones sinuosos, cercado de montañas por todos lados.",
		full = "Las Tierras Inhóspitas son un desierto agrietado de tierra seca, rocas dispersas y cañones sinuosos, cercado de montañas por todos lados. Poco sobrevive aquí salvo coyotes, pumas y zopilotes.\n\nEn el extremo norte se encuentran las ruinas de Uldaman, obra de los antiguos terráneos. Cuando fue desenterrada, ofreció las primeras pistas sobre el elevado origen de los enanos, y los prospectores de Forjaz acudieron en masa para buscar artefactos de los titanes en la ruina. Pero los troggs Grutacanto, despertados tras milenios de letargo, masacraron a los exploradores y ahora defienden con salvaje determinación la ciudad que han robado. Justo al sur de Uldaman se alza una gran fortaleza Hierro Negro, cuyos enanos combaten contra los ogros de la tribu Dustbelcher y contra los dracos que anidan entre la progenie de dragones negros del este.\n\nMás tarde se fundó aquí Kargath, el único puesto de la Horda en Khaz Modan, levantado para que los orcos pudieran vigilar a sus parientes renegados de Roca Negra. El propio Jefe de Guerra Thrall envió a la Fuerza Expedicionaria de Kargath para dar caza a Rend Puño Negro.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Las Tierras Devastadas",
		short = "Las Tierras Devastadas hacen honor a su nombre. La arcilla roja que se pisa aquí fue antaño tierra parda, parte de una oscura ciénaga llamada la Ciénaga Negra, antes de que la Horda orca abriera aquí el Portal Oscuro y se derramara sobre Azeroth.",
		full = "Las Tierras Devastadas hacen honor a su nombre. La arcilla roja que se pisa aquí fue antaño tierra parda, parte de una oscura ciénaga llamada la Ciénaga Negra, antes de que la Horda orca abriera aquí el Portal Oscuro y se derramara sobre Azeroth. La magia que se filtró aquel día abrasó el suelo hasta volverlo rojo y lo mató para siempre. Aquí ya no crece nada salvo matorrales resistentes del desierto, y criaturas del desierto igual de resistentes: basiliscos, escorpiones y hienas.\n\nEl archimago Khadgar y el Kirin Tor levantaron el Castillo de Nethergarde para vigilar las ruinas del portal y asegurarse de que nada volviera a cruzarlo. La paz duró dos años, hasta que la Horda de Draenor reabrió el Portal y asedió el castillo. Cuando el ritual de Ner'zhul empezó a desgarrar Draenor, Khadgar y los demás magos usaron el Cráneo de Gul'dan para hacer añicos el marco de piedra del Portal desde el otro lado, cortando para siempre el puente entre los mundos.\n\nHoy los magos y paladines de Nethergarde siguen manteniendo su sombría vigilancia sobre el Portal muerto, una comunidad cerrada y sin humor que no confía en nadie y no perdona ningún descuido, el único refugio que puede hallarse en una tierra donde las tormentas del mar oriental resbalan sobre el suelo cocido antes de hacer ningún bien.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Claros de Tirisfal",
		short = "El cielo sobre los Claros de Tirisfal lleva años teñido de un verde enfermizo, y los árboles se aferran a la poca vida que la peste les dejó.",
		full = "El cielo sobre los Claros de Tirisfal lleva años teñido de un verde enfermizo, y los árboles se aferran a la poca vida que la peste les dejó. Antaño estas eran pacíficas granjas bajo el rey Terenas, donde generaciones vivían tranquilas entre molinos y campos de calabazas. Aquello terminó cuando Arthas Menethil saqueó Lordaeron y propagó la peste por el campo, matando a sus gentes y alzándolas como esclavas del Rey Exánime. Las fosas comunes aún señalan dónde los muertos eran demasiados para enterrarlos como es debido. Fue cerca de la Hacienda Balnir, meses después, donde Sylvanas Brisaveloz volvió a sus almas en pena contra Arthas y clavó una flecha envenenada al caballero de la Muerte antes de que los esqueletos de Kel'Thuzad la obligaran a huir.\n\nDe aquella ruina surgieron los Renegados, los muertos de Sylvanas dotados de libre albedrío, que reclamaron la tierra como propia. Sus enemigos nunca se marcharon: la Cruzada Escarlata ocupa el viejo Monasterio Escarlata en el norte, fanáticos que queman y persiguen todo lo que no sea humano.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Bosque de Argénteos",
		short = "El Bosque de Argénteos, o simplemente Argénteos, es un bosque vasto y antiguo que se extiende a lo largo de la escarpada costa occidental de Lordaeron. El terreno varía de bastante llano a ondulado, y se encuentra enclavado entre montañas aún más altas.",
		full = "El Bosque de Argénteos, o simplemente Argénteos, es un bosque vasto y antiguo que se extiende a lo largo de la escarpada costa occidental de Lordaeron. El terreno varía de bastante llano a ondulado, y se encuentra enclavado entre montañas aún más altas. El bosque guarda un silencio inquietante, roto solo por algún aullido antinatural que resuena entre los árboles de vez en cuando. Los salientes cubiertos de musgo tiemblan con la brisa fría, y todos los árboles están enfermos o moribundos. Granjas ruinosas y minas abandonadas salpican la tierra, convertidas ahora en hogar de los habitantes más oscuros del bosque.\n\nEste bosque está encantado y es salvaje, y se caracteriza por sus altos pinos de corteza plateada que se alzan sobre colinas cubiertas de hierba. La Alianza protegió antaño el Bosque de Argénteos, cuando era frondoso y rebosaba vida. Ahora el lugar está envuelto en brumas fantasmales. Los Renegados controlan el norte del bosque y chocan constantemente con los miserables gnolls Putrepellejo. Lo que queda de la población humana conserva el control del sur del bosque, pero están desesperados y sus fuerzas, muy dispersas. Dalaran envía con frecuencia expediciones a Argénteos para defender a estas gentes y estudiar la peste de la no-muerte y la maldición de los ferocanis, una misteriosa afección que hace que sus víctimas se transformen en sanguinarios ferocanis licántropos cuando sale la luna.\n\nGilneas y las Laderas de Trabalomas lindan con el bosque por el sur, mientras que los Claros de Tirisfal quedan al norte. El Lago Lordamere hace de frontera oriental de Argénteos.\n\nAunque el territorio pertenece a los Renegados, su derecho lo disputan los magos de Dalaran y los agentes de la Plaga, que se han adueñado de algunos de los campos y granjas en ruinas. Los gnolls Putrepellejo operan desde la misteriosa Isla de Fenris y atacan con ferocidad a cualquiera que se atreva a acercarse a sus asuntos. Al suroeste se encuentra la Aldea Piroleña, cuyas gentes han caído bajo la maldición del archimago Arugal y se transforman en sanguinarios ferocanis al caer la noche. Arugal habita en las cercanas torres sombrías del Castillo de Colmillo Oscuro.\n\nEl Bosque de Argénteos es escenario frecuente de batallas, pues las fuerzas de la Alianza procedentes de Costasur viajan a estos bosques malditos para atacar El Sepulcro o entrar en Colmillo Oscuro. Es el límite de la patria de los Renegados, y el punto más meridional donde pueden verse los efectos de la peste de la no-muerte en la vegetación.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Tierras de la Peste del Oeste",
		short = "Antaño estas eran las tierras de cultivo más hermosas del norte de Lordaeron, boscosas y verdes, que llenaban los graneros del reino desde Andorhal y se gobernaban desde el salón de Vega del Amparo.",
		full = "Antaño estas eran las tierras de cultivo más hermosas del norte de Lordaeron, boscosas y verdes, que llenaban los graneros del reino desde Andorhal y se gobernaban desde el salón de Vega del Amparo. Aquella prosperidad se convirtió en el arma con la que fueron destruidas.\n\nSiguiendo el designio del Rey Exánime, el Culto de los Malditos llevó sus energías de la peste hacia el sur en calderos portátiles, ocultándolos en aldeas de cultistas leales y colocando los cuatro más grandes en los propios campos de Andorhal. El mismo grano quedó contaminado, y salió por todo Lordaeron en carros que nadie pensó en cuestionar. Las gentes que comieron su propio pan enfermaron, murieron y se alzaron de nuevo como esclavos del Rey Exánime. Los bosques nunca se recuperaron. Los pinos se alzan grises, con las agujas pardas, bajo una neblina enfermiza, y sus troncos están hinchados de excrecencias tumorales.\n\nEl poco orden que queda se rescató tras el colapso del reino, cuando la Cruzada Escarlata se apoderó del Fuerte de Mardenholde, en Vega del Amparo, y desde allí atacó a los no-muertos que dominaban el resto de la tierra. En medio de todo ello, un único lugar conserva algo de paz: la Tumba de Uther, consagrada a Uther el Iluminado, un suelo que la plaga jamás ha tocado.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Tierras de la Peste del Este",
		short = "Este suelo fue antaño tierra de cultivo, donde las aldeas de la Foresta Oriental se repartían alrededor de Stratholme, la segunda ciudad de Lordaeron. Nada de aquello queda.",
		full = "Este suelo fue antaño tierra de cultivo, donde las aldeas de la Foresta Oriental se repartían alrededor de Stratholme, la segunda ciudad de Lordaeron. Nada de aquello queda. La tierra está ahora parda y enferma, los árboles se han hinchado hasta parecer hongos y el aire está cargado de una bruma anaranjada.\n\nFue a Stratholme adonde llegó el príncipe Arthas, buscando el origen de una peste que ya se había cobrado a los habitantes del pueblo. Lord Uther, maestro de la Mano de Plata, se negó a permitir que purgara la ciudad. Arthas lo despojó del mando, disolvió la Mano de Plata en ese mismo instante y pasó él mismo a cuchillo a la gente de Stratholme antes que dejar que se alzaran como parte de la Plaga. No se detuvo ahí: persiguió al señor del terror Mal'Ganis hasta el norte, regresó convertido en caballero de la Muerte y mató a su propio padre para poner fin al reino de Lordaeron.\n\nAlexandros Mograine alzó una Cruzada con los restos de la Mano de Plata para recuperar la tierra en ruinas, y se apoderó de Mano de Tyr y de media Stratholme antes de que su muerte dividiera su orden en el Alba Argenta y la Cruzada Escarlata, que aún ocupa estos campos, combatiendo sin fin contra la Plaga y sin dar la bienvenida a nadie más.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Laderas de Trabalomas",
		short = "El suelo de Trabalomas es fértil y sus colinas verdes, y los viajeros dicen que así era todo Lordaeron antes de que llegara la Peste.",
		full = "El suelo de Trabalomas es fértil y sus colinas verdes, y los viajeros dicen que así era todo Lordaeron antes de que llegara la Peste. En eso reside tanto su crueldad como su consuelo: la tierra recuerda lo que se perdió en todas partes, mientras quienes la ocupan luchan en la misma guerra que arruinó el resto.\n\nAl comienzo de la Segunda Guerra, los asaltantes orcos golpearon sus pueblos costeros, y el propio Orgrim Martillo Maldito cabalgó contra el Castillo de Durnholde para liberar a Zul'jin de sus celdas. Décadas después fue Thrall quien atravesó estas colinas, reuniendo a los clanes orcos dispersos antes de colarse de noche en Costasur para robar sus barcos y llevar a la nueva Horda al otro lado del mar, hasta Kalimdor.\n\nLo que empezaron los orcos lo han continuado los Renegados. Reclamaron el Molino Tarren como su posesión más meridional y lo convirtieron en una base de operaciones contra los humanos de Costasur y de los Campos de Trabalomas, que se mantuvieron firmes por la Alianza.\n\nHoy los pinares salpican las tierras de cultivo, y los caminos aún cruzan los pastos hacia los sombríos asentamientos de los Renegados en el norte, como si la propia tierra siguiera esperando a ver qué bando se queda con ella.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "Tierras del Interior",
		short = "Tras la guerra de los Tres Martillos, los enanos Martillo Salvaje abandonaron sus túneles de Grim Batol y se dirigieron al norte, donde construyeron sus hogares en la superficie, en Pico Nidal.",
		full = "Tras la guerra de los Tres Martillos, los enanos Martillo Salvaje abandonaron sus túneles de Grim Batol y se dirigieron al norte, donde construyeron sus hogares en la superficie, en Pico Nidal. Se apartaron de la piedra y la forja para volverse hacia el cielo y las alas, y se unieron tan estrechamente a los grifos salvajes de la región que alzaron un gran grifo de piedra en su propia ciudad para honrar ese vínculo. Los trols del bosque que ya ocupaban esta tierra, restos del otrora gran Imperio Amani, vieron a los enanos como intrusos en suelo ancestral y asaltaban los nidales siempre que podían.\n\nCuando la Horda irrumpió durante la Segunda Guerra, el thane Kurdran Martillo Salvaje y sus jinetes, que hasta entonces ni siquiera sabían que existieran tales invasores, cayeron desde el cielo sobre las columnas orcas con martillos cargados de tormenta y las acosaron sin descanso. Orgrim Martillo Maldito esperaba atraer las fuerzas de la Alianza hacia las Tierras del Interior para poder golpear Quel'Thalas sin oposición, pero Anduin Lothar adivinó el plan y cabalgó él mismo junto a Kurdran, y juntos derrotaron a los invasores y los hicieron retroceder hasta las Montañas de Alterac. Por ello, Kurdran comprometió la ayuda de su pueblo con la Alianza.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "La nieve cubre en abundancia Dun Morogh, cercada por todos lados por las montañas de Khaz Modan, y sus pasos están siempre vigilados por tropas enanas.",
		full = "La nieve cubre en abundancia Dun Morogh, cercada por todos lados por las montañas de Khaz Modan, y sus pasos están siempre vigilados por tropas enanas. Antes de pertenecer a nadie más, las montañas pertenecieron a los trols de hielo Peloescarcha, que se habían asentado en la región tras separarse del Imperio Drakkari en épocas remotas.\n\nAquello cambió cuando los primeros gnomos salieron de Uldaman y aplicaron su ingenio a sobrevivir tanto al frío como a los trols, excavando moradas fortificadas en lo profundo de las cumbres. Quinientos años después, los enanos los siguieron fuera de Uldaman, atraídos por las mismas montañas que habían divisado en el horizonte, y levantaron Forjaz bajo la más alta de ellas. Al encontrar a los gnomos ya asentados cerca, ambos pueblos forjaron una amistad que nunca se ha roto: los enanos prestaron su fuerza para levantar Gnomeregan y los gnomos compartieron los secretos de sus máquinas. Juntos, sus ejércitos derrotaron a los trols Peloescarcha y obligaron a los supervivientes a retirarse a las colinas, poniendo fin para siempre al dominio de los trols sobre la tierra.\n\nGnomeregan ya no existe, está en ruinas, y su pueblo se hacina en Forjaz en busca de refugio.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "La Garganta de Fuego",
		short = "Antaño esta era una tierra verde, parte de las Montañas Crestagrana, hasta que el propio suelo se desgarró hace más de doscientos treinta años.",
		full = "Antaño esta era una tierra verde, parte de las Montañas Crestagrana, hasta que el propio suelo se desgarró hace más de doscientos treinta años.\n\nEn la guerra de los Tres Martillos, el thane hechicero Thaurissan, de los enanos Hierro Negro, buscó un arma con la que doblegar a sus enemigos. Él y siete de sus enanos de mayor confianza tendieron la mano bajo el mundo e invocaron poderes que debieron haber seguido dormidos. Lo que respondió no fue un sirviente, sino un amo: el antiguo Señor del Fuego Ragnaros. Su despertar arrancó la Montaña Roca Negra de la tierra, ennegreció el terreno a lo largo de kilómetros y aplastó bajo ella hasta los escombros la capital Hierro Negro de Thaurissan. Las estepas calcinadas del sur pasaron a conocerse como las Estepas Ardientes; este valle asolado del norte se convirtió en la Garganta de Fuego.\n\nNo todos los Hierro Negro permanecieron leales a su clan tras la catástrofe. Algunos se separaron, se llamaron a sí mismos la Hermandad del Torio y construyeron el Puesto del Torio con vistas a la gran excavación que sus antiguos parientes habían abierto en el fondo del valle, vigilando desde lo alto las labores de los Hierro Negro.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Las Estepas Ardientes",
		short = "El cielo sobre las Estepas Ardientes nunca pierde su tono rojizo, iluminado por las erupciones esporádicas de la Montaña Roca Negra, y el suelo nunca se enfría.",
		full = "El cielo sobre las Estepas Ardientes nunca pierde su tono rojizo, iluminado por las erupciones esporádicas de la Montaña Roca Negra, y el suelo nunca se enfría. Doscientos años antes de que se abriera el Portal Oscuro, los enanos Hierro Negro llegaron aquí exiliados de Forjaz. Su thane hechicero, Thaurissan, quiso invocar esbirros elementales para ganar la guerra de los Tres Martillos contra los clanes Barbabronce y Martillo Salvaje. Lo que respondió no fue un esbirro, sino Ragnaros, el Señor del Fuego, desterrado en su día por los titanes. Su llegada fundió las montañas a su alrededor, alzó un volcán en el corazón de la explosión y destruyó a los enanos que lo habían invocado. Lo que quedaba al norte de aquel nuevo pico se convirtió en la Garganta de Fuego; lo que quedaba al sur, en las Estepas Ardientes, marcadas desde entonces.\n\nLos orcos se asentaron en las laderas del volcán durante la Primera Guerra y conservaron la Cumbre de Roca Negra como bastión durante la Segunda. Los orcos Roca Negra regresaron después y aún siguen allí, fieles a las viejas y brutales costumbres de antes de la tregua de Thrall. Los dragones negros al mando de Nefarian ocupan los niveles superiores de la cumbre, y se dice que Ragnaros aún medita en algún lugar bajo todo ello.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Bosque de Elwynn",
		short = "Cuando los orcos llegaron en la Primera Guerra, miles de ellos marcharon a través de Elwynn para rodear Ventormenta, aislándola de todo salvo del mar.",
		full = "Cuando los orcos llegaron en la Primera Guerra, miles de ellos marcharon a través de Elwynn para rodear Ventormenta, aislándola de todo salvo del mar. El campeón Anduin Lothar encabezó a los Caballeros de Ventormenta en una carga a través del propio bosque, sorprendiendo a la retaguardia orca y dispersándola. Aquello le dio tiempo a la ciudad, pero no el suficiente. El Jefe de Guerra Puño Negro no tardó en tomar Villadorada y Arroyo de la Luna, las últimas poblaciones que se interponían entre la Horda y el rey, y el Castillo de Ventormenta fue saqueado. Lothar condujo a los supervivientes hasta el mar y lejos, hacia Lordaeron, y las ruinas de la ciudad pertenecieron durante un tiempo al clan Cazatormentas. Las catapultas orcas dispersas aún yacen rotas y pudriéndose por toda la región, los únicos recuerdos que quedan de aquella ocupación.\n\nLos Viñedos de Villanorte, al este de la ciudad, fueron antaño el orgullo de los granjeros de Ventormenta. Cuando el Gremio de Canteros no cobró los años que pasó reconstruyendo la capital en ruinas, y los nobles lo disolvieron antes que saldar la deuda, la furia del maestro del gremio Edwin VanCleef se extendió en disturbios que costaron la vida a la reina Tiffin Ellerian Wrynn y dieron origen a la Hermandad Defias. La Hermandad expulsó a los granjeros de Villanorte y ocupó sus campos.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Paso de la Muerte",
		short = "El Paso de la Muerte atraviesa las montañas del centro de Azeroth y une el Bosque del Ocaso con el Pantano de las Penas. Hace una veintena de años se consideraba parte de las Montañas Crestagrana.",
		full = "El Paso de la Muerte atraviesa las montañas del centro de Azeroth y une el Bosque del Ocaso con el Pantano de las Penas. Hace una veintena de años se consideraba parte de las Montañas Crestagrana.\n\nLa Torre de Marfil de Karazhan, antaño sede del poder del oscuro mago Medivh, se alza en el centro de esta región escarpada y filtra magia maligna en la tierra. Los árboles están petrificados y sin hojas, y un viento terrible gime a través del cañón. Ogros, demonios, no-muertos y unos pocos gitanos humanos vagan por el interior, y se susurra que una nueva fuerza se ha adueñado de la Torre de Marfil, y que los ogros y los demonios están bajo su dominio.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Bosque del Ocaso",
		short = "Un manto de noche antinatural cubre el Bosque del Ocaso, y nunca se ha levantado.",
		full = "Un manto de noche antinatural cubre el Bosque del Ocaso, y nunca se ha levantado. Lo que antaño fue una hermosa extensión del Bosque de Elwynn es ahora una tierra maldita y moribunda: los árboles crecieron retorcidos bajo la niebla negra, los muertos se alzaron de sus tumbas y los ferocanis llegaron sigilosos con la propia oscuridad, atraídos por el poder de la Guadaña de Elune. Los ogros que avanzan desde el Paso de la Muerte no han hecho más que agravar la desdicha.\n\nHace mucho que la protección de Ventormenta dejó de significar nada aquí, y quienes permanecen han aprendido a defenderse sin ella. Su milicia, la Guardia Nocturna, patrulla los caminos y protege Villa Oscura de todo lo que se mueve en las sombras: guerreros esqueléticos y necrófagos, ferocanis salvajes y, además, hombres de los Defias.\n\nEn el corazón del bosque se encuentra el cráter de un volcán extinto hace mucho, envuelto en un crepúsculo más suave que la oscuridad que lo rodea. En su interior se alza uno de los Grandes Árboles, cuyas raíces se extienden hacia el Sueño Esmeralda, y la influencia de los druidas durmientes tiñe todo lo que crece a su alrededor. Más allá se extienden granjas abandonadas y las extensas tumbas del Cementerio del Cerro del Cuervo, que se han ido llenando año tras año desde que cayó la oscuridad.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "Las aguas de Loch Modan descansan acunadas en piedra gris, contenidas por la Presa de las Tres Cabezas, una obra de ingeniería enana que ninguna otra construcción de Azeroth ha igualado jamás.",
		full = "Las aguas de Loch Modan descansan acunadas en piedra gris, contenidas por la Presa de las Tres Cabezas, una obra de ingeniería enana que ninguna otra construcción de Azeroth ha igualado jamás. Las montañas se alzan escarpadas por todos lados, con escasos bosques de pinos y abedules, y el propio lago permanece quieto y silencioso, como si nada lo hubiera perturbado nunca.\n\nEl lago fue una vez un campo de batalla. En la Segunda Guerra, los orcos de la Horda irrumpieron en la región y se enfrentaron aquí a la Alianza. Forjaz resistió. Sus enanos rechazaron a los orcos y recuperaron Loch Modan, y los restos de aquella guerra nunca se retiraron del todo: catapultas rotas y balistas destrozadas aún yacen esparcidas por el lecho del lago y sus islas, medio hundidas, la única prueba que queda de que estas aguas tranquilas fueron alguna vez un campo de matanza.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Montañas Crestagrana",
		short = "Las Montañas Crestagrana se encuentran al este del Bosque de Elwynn, al noreste del Bosque del Ocaso y al sur de las Estepas Ardientes.",
		full = "Las Montañas Crestagrana se encuentran al este del Bosque de Elwynn, al noreste del Bosque del Ocaso y al sur de las Estepas Ardientes.\n\nRegión idílica de ríos caudalosos, olmos altísimos y terreno que se eleva, Crestagrana está bajo la protección de Ventormenta, aunque desde la Segunda Guerra es técnicamente independiente. Sigue siendo una de las últimas regiones pacíficas de Azeroth, con gentes tranquilas y satisfechas que abastecen a Ventormenta de madera, pescado y cosechas. Sin embargo, la paz es imperfecta: una fuerza de orcos Roca Negra procedente de las Estepas Ardientes ocupa el Fuerte de Petravista, aunque de momento se mantienen apartados. Comparada con la ruina de los Páramos de Poniente, Crestagrana aún se mantiene en pie.\n\nEn la orilla norte del Lago Sempiterno se alza el pueblo de Villa del Lago, asediado por gnolls y orcos Roca Negra que bajan de las colinas circundantes. Al sur, el cruce conocido como Tres Caminos une Villa del Lago con Elwynn y el Bosque del Ocaso, y, por el Camino del Lago, con el Fuerte de Petravista, una ruta dominada por crías de dragón, gnolls, múrlocs y bestias salvajes.\n\nLa superficie del lago parece bastante tranquila, pero los múrlocs acechan bajo ella, y persisten los rumores sobre un monstruo marino en sus profundidades.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Vega de Tuercespina",
		short = "La Vega de Tuercespina es una vasta jungla situada al sur del Bosque del Ocaso. Los trols de la jungla patrullan esta humeante selva tropical y los nagas cazan a lo largo de sus costas, mientras que las enredaderas espinosas y las bestias hacen que viajar sea peligroso.",
		full = "La Vega de Tuercespina es una vasta jungla situada al sur del Bosque del Ocaso. Los trols de la jungla patrullan esta humeante selva tropical y los nagas cazan a lo largo de sus costas, mientras que las enredaderas espinosas y las bestias hacen que viajar sea peligroso.\n\nLa vega fue antaño el corazón del Imperio Gurubashi, cuyas grandes ciudades se alzaban por toda la región. Tras la caída del imperio, aquellas ciudades se desmoronaron hasta quedar en ruinas, aunque los trols aún habitan entre ellas. Zul'Gurub, al noreste, fue en su día la capital Gurubashi.\n\nBahía del Botín fue originalmente un pequeño pueblo portuario fundado por humanos, hasta que fue arrasado por los trols. Los goblins del Cártel Bonvapor expulsaron más tarde a los trols de la cala y la reclamaron como propia, convirtiéndola en su centro de operaciones en los Reinos del Este.\n\nEn el norte se alza un campamento levantado por la expedición del coronel Kurzen. Allí, la mente del coronel fue dominada por un mago ogro, Mai'Zoth, que utilizó un artefacto llamado el Ojo de la mente para doblegar la voluntad de Kurzen y dar órdenes a sus hombres. Algunos de los soldados de Kurzen se rebelaron contra su comandante poseído y huyeron hacia el oeste, donde fundaron un campamento rebelde en desafío a él.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Pantano de las Penas",
		short = "Bajo las aguas negras del pantano yace un templo más antiguo que el pesar que dio nombre a este lugar.",
		full = "Bajo las aguas negras del pantano yace un templo más antiguo que el pesar que dio nombre a este lugar. Cuando cayó el Imperio Gurubashi, una banda renegada de trols llamada los Atal'ai huyó a la ciénaga y levantó el Templo de Atal'Hakkar, donde practicaron ritos macabros para devolver al mundo a su oscuro loa, Hakkar el Desollalmas. Su magia retorció las plantas y bestias alrededor del templo hasta que la corrupción no pudo pasar desapercibida. Ysera, señora de los sueños, supo de las ambiciones del culto y volvió su poder contra ellos, hundiendo el templo bajo la mayor de las ciénagas antes de que Hakkar pudiera regresar. Pero no confiaba en que los trols abandonaran a su dios para siempre. Dispuso que su consorte Eranikus y una hueste de dragones verdes montaran guardia eterna sobre la ruina, para que nunca más pudiera usarse para desatar semejante mal sobre el mundo. Los dracónidos verdes aún patrullan estas ciénagas por orden suya, y el templo hundido sigue sellado bajo el agua, vigilado en lugar de destruido.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Páramos de Poniente",
		short = "El viento corre ahora sin obstáculos por los campos de los Páramos de Poniente, pues no queda nada alto que lo detenga. Antaño esto fue el granero de Ventormenta, que alimentó al joven reino durante generaciones.",
		full = "El viento corre ahora sin obstáculos por los campos de los Páramos de Poniente, pues no queda nada alto que lo detenga. Antaño esto fue el granero de Ventormenta, que alimentó al joven reino durante generaciones.\n\nCuando el Gremio de Canteros no cobró por reconstruir Ventormenta tras la Segunda Guerra, y la guardia se volvió contra sus protestas, el maestro del gremio Edwin VanCleef llevó a sus hombres a esconderse en el campo antes que enfrentarse a la justicia del rey Varian. Allí se convirtieron en la Hermandad Defias, y bajo un granero de Arroyo de la Luna, VanCleef encontró una antigua red de minas lo bastante profunda como para ocultar la construcción de un arma destinada a arrasar Ventormenta desde el mar. Expulsó a los granjeros, contrató a gnolls Zarparrío para dominar la tierra e hizo que sus hombres quemaran los campos y salaran la tierra para que nada volviera a crecer en ella.\n\nVentormenta, con las arcas vacías, dejó que los Páramos de Poniente se las arreglaran solos. Solo Gryan Mantorrecio respondió, formando las Milicias del Pueblo en la Colina del Centinela cuando ningún ejército acudió.\n\nLos campos que él saló no se lo han perdonado a los Páramos de Poniente. La hierba aún crece amarilla y rala donde antes el trigo llegaba a la altura de los hombros.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Los Humedales",
		short = "Una ciénaga fría y gris se extiende bajo la presa, con bruma sobre sus ríos y estanques, montañas que la cercan por tres lados y el mar abierto al oeste.",
		full = "Una ciénaga fría y gris se extiende bajo la presa, con bruma sobre sus ríos y estanques, montañas que la cercan por tres lados y el mar abierto al oeste. Hay escombros esparcidos por ella, restos de las fortalezas enanas que antaño dominaron este terreno. Ahora son los múrlocs, las bestias salvajes y los orcos renegados quienes la dominan, y el Puerto de Menethil es el único bastión verdadero de la Alianza aquí.\n\nAquel puerto no siempre fue territorio de la Alianza. Cuando comenzó la Segunda Guerra, Orgrim Martillo Maldito construyó su flota de invasión en una pequeña isla de la Bahía de Baradin, para que sus barcos pudieran atacar las costas de Lordaeron sin enfrentarse a sus defensas terrestres. Los Humedales pagaron por ello: los orcos y los dragones se alimentaron vorazmente de la tierra y la caza escaseó. Después de la guerra, el puerto fue reconstruido y rebautizado como Puerto de Menethil, en honor a Terenas Menethil II.\n\nDespués llegó la caída de Grim Batol. El Vuelo Rojo, esclavizado para servir allí al clan Faucedraco, se volvió contra sus captores en cuanto fue liberado, y el clan quedó destrozado, con sus supervivientes dispersos por las tierras salvajes. Alexstrasza consideró que era responsabilidad de su vuelo mantener sellada la montaña, y desde entonces los dragonantes rojos montan guardia sobre ella.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Cuando Malfurion Tempestira desapareció en el Sueño Esmeralda, el archidruida Fandral Corzocelada pasó a dirigir el Círculo Cenarion en su lugar y convenció al Círculo de los Ancestros de que había llegado el momento de hacer crecer un nuevo Árbol del Mundo y recuperar la inmortalidad que los elfos de la noche habían perdido.",
		full = "Cuando Malfurion Tempestira desapareció en el Sueño Esmeralda, el archidruida Fandral Corzocelada pasó a dirigir el Círculo Cenarion en su lugar y convenció al Círculo de los Ancestros de que había llegado el momento de hacer crecer un nuevo Árbol del Mundo y recuperar la inmortalidad que los elfos de la noche habían perdido. En el Mar de la Bruma alzaron Teldrassil, corona de la tierra, y construyeron Darnassus en sus ramas. Pero Nozdormu, que había bendecido el primer Árbol del Mundo, rechazó este, calificando el deseo de arrogante, y la inmortalidad que buscaban los elfos de la noche nunca llegó.\n\nCon el tiempo, las tierras de lo alto de Teldrassil cayeron bajo una presencia siniestra. Los fúrbolgs y los grells de sus bosques enloquecieron, aparecieron sátiros entre los árboles, y las grandes tortugas y trilladoras que antes nadaban en las aguas que rodean el árbol huyeron para varar y morir en las costas de Costa Oscura. El origen de esta corrupción sigue siendo un misterio, y Malfurion no ha regresado del Sueño para buscarlo.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Costa Oscura",
		short = "Una niebla gris se extiende por esta costa la mayor parte del tiempo, y los elfos de la noche la han tomado desde hace mucho como una advertencia.",
		full = "Una niebla gris se extiende por esta costa la mayor parte del tiempo, y los elfos de la noche la han tomado desde hace mucho como una advertencia. La lluvia y la roca hacen que la tierra sea inhóspita, y todo intento de asentarse en ella más allá del puesto comercial de Auberdine ha quedado en nada.\n\nHace diez mil años se alzaban aquí las ciudades gemelas de Ameth'Aran y Bashal'Aran, gobernadas por Athrikus Narassin. Cuando la Guerra de los Ancestros quebró el mundo y sobrevino el Gran Diluvio, Athrikus juró a su pueblo que lo salvaría. Cumplió la letra de su promesa y traicionó su espíritu: ató sus almas a gemas de alma, diciéndoles que aquello era la vida eterna, mientras en realidad los drenaba para alimentar su propio poder. Las ciudades cayeron en ruinas, y lo que camina hoy entre sus piedras no descansa del todo en paz.\n\nTras la Tercera Guerra, Fandral Corzocelada trajo a Costa Oscura a druidas del Círculo Cenarion y plantó un nuevo Árbol del Mundo, Teldrassil, frente a esta costa.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Vallefresno",
		short = "Vallefresno es un bosque antiguo, denso en árboles viejos y magia antigua, y nunca ha dejado de ser objeto de disputa.",
		full = "Vallefresno es un bosque antiguo, denso en árboles viejos y magia antigua, y nunca ha dejado de ser objeto de disputa.\n\nLos orcos del clan Grito de Guerra llegaron aquí primero como leñadores. Los goblins a las órdenes de Neeloc Tacañón talaron los árboles hasta que los fúrbolgs de la zona los hicieron retroceder, y Grommash Hellscream derrotó a su vez a los fúrbolgs y a las Centinelas para conservar la ayuda de los goblins. El propio Cenarius acudió para restaurar lo que se había talado, y le costó la vida: los amos de la Legión Ardiente convirtieron su confianza en una trampa, y Grommash lo abatió.\n\nLo peor llegó cuando la Legión marchó sobre Vallefresno con todas sus fuerzas. Los infernales de Archimonde cayeron ardiendo del cielo, y los no-muertos y los demonios irrumpieron desde el este, arrollando a los divididos ejércitos de elfos de la noche, orcos y humanos por igual antes de avanzar hacia el Monte Hyjal. Tyrande Susurravientos despertó a Malfurion del Sueño Esmeralda, y este encontró el bosque que recordaba consumido por el fuego vil y una plaga asfixiante.\n\nAquella vieja contienda nunca terminó. Los elfos de la noche aún conservan Astranaar y sus refugios dispersos; la Horda ha llevado sus campamentos Grito de Guerra hasta lo más profundo del sur y del este, talando madera y haciendo retroceder a las Centinelas. Ninguno de los dos bandos ha terminado nunca la lucha por estos bosques.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Las Mil Agujas",
		short = "El cañón es profundo y seco, con el fondo perdido entre imponentes mesetas, hasta que en el este se abre al Desierto de Sal, una gran salina bajo un cielo inmenso.",
		full = "El cañón es profundo y seco, con el fondo perdido entre imponentes mesetas, hasta que en el este se abre al Desierto de Sal, una gran salina bajo un cielo inmenso. El amanecer visto desde el Poblado Viento Libre o desde las alturas que rodean la Cumbre de la Nube Negra es todo un espectáculo sobre un paisaje tan yermo. El druida Quentin se ha preguntado si la dura sequedad de este lugar, tan pegada a la exuberante jungla de la vecina Feralas, no será en absoluto algo natural, sino la huella de alguna extraña magia obrada sobre la tierra.\n\nLas altas mesetas pertenecen a los tauren, y el Poblado Viento Libre es su bastión entre ellas. No conservaron este terreno sin desafíos. Los centauros de la zona los presionaron y, peor aún, sus propios parientes de la tribu Tótem Siniestro se volvieron contra ellos, de modo que los tauren del Poblado Viento Libre se vieron obligados a luchar tribu contra tribu por las tierras altas. Solo con la ayuda de la Horda lograron hacer retroceder a los centauros y a los Tótem Siniestro.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Sierra Espolón",
		short = "La Cima del Espolón siempre perteneció a los espíritus antes que a ningún pueblo.",
		full = "La Cima del Espolón siempre perteneció a los espíritus antes que a ningún pueblo. Los elfos de la noche mantienen un túmulo y un claro en su cumbre, donde comulgan con la naturaleza, y los tauren también la consideran sagrada, pues fue aquí donde el Oráculo inmortal observó en su día los hilos del destino mientras la Madre Tierra los tejía. La leyenda cuenta que los primeros tauren que se asentaron en estas montañas subieron tótems llameantes hasta los riscos más altos y encendieron hogueras a An'she para hacer retroceder la oscuridad que se aferraba a la piedra.\n\nMás abajo en la montaña, Elune bendijo hace mucho una fuente con el don de la salud. Más tarde, las arpías tomaron los picos cercanos, capturaron a los dracoleones que anidaban allí y corrompieron las aguas de la fuente. Thrall se enfrentó a ellas, con Cairne Pezuña de Sangre y sus tauren a su lado, y derrotó a una banda de centauros para obtener un Glifo de Purificación y limpiar lo que las arpías habían corrompido. Los dracoleones liberados los llevaron hasta la propia Cima.\n\nAquella vieja paz con la tierra ha desaparecido en el sur. Ventura y Cía. ha dejado pelado el Risco Cortaviento, talando sus árboles, ahogando el aire con hollín y ensuciando el agua con aceite y desechos, hasta que los espíritus de la montaña clamaron con tanta fuerza que los chamanes los oyeron hasta en Orgrimmar.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolace",
		short = "Theradras, hija de Therazane la Madre Piedra, dormía antaño bajo una fértil pradera.",
		full = "Theradras, hija de Therazane la Madre Piedra, dormía antaño bajo una fértil pradera. Los chamanes tauren, creyendo que la propia Madre Tierra habitaba bajo ella, la llamaron durante décadas hasta que por fin algo respondió: no la Madre Tierra, sino Theradras, despertada furiosa de su sueño. Se alimentó de la tierra para restaurar su debilitada forma, y los prados murieron en un instante. Los tauren llamaron Desolace a lo que quedó.\n\nZaetar, hijo del señor del bosque Cenarius, acudió para someterla, pero en cambio la amó, y ella le correspondió. De su unión nacieron los centauros, y su primer acto fue asesinar a su propio padre. Se multiplicaron con rapidez y expulsaron a los tauren de la tierra, dando inicio a siglos de guerra entre ambas razas.\n\nTheradras aún habita en Maraudon, bajo los cañones occidentales, y es allí donde los centauros sitúan el nacimiento de su raza.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Feralas se alza extraña entre sus vecinas, una selva de árboles antiguos allí donde las tierras yermas que la rodean solo prometen polvo.",
		full = "Feralas se alza extraña entre sus vecinas, una selva de árboles antiguos allí donde las tierras yermas que la rodean solo prometen polvo. Entre su verdor se hallan dispersas las ruinas de los elfos, medio devoradas por raíces y enredaderas, y la mayor de ellas es la ciudad enterrada de La Masacre.\n\nLos ogros Gordunni dominan ahora Feralas, y la han hecho suya destrozándola. Han arrasado extensiones enteras de bosque, y su corrupción se ha asentado sobre la tierra como una enfermedad. Más allá de los muros de La Masacre, sus partidas de asalto queman aldeas y asesinan a los viajeros en los bosques del sur, una corrupción que se extiende por las tierras salvajes y cuyo origen se remonta a las ruinas de abajo.\n\nLos tauren Tótem Siniestro aún viven dispersos por la región, perseguidos por quienes recuerdan lo que ha hecho la tribu.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Marjal Revolcafango",
		short = "Aquí los mosquitos no paran nunca, y el barro tampoco.",
		full = "Aquí los mosquitos no paran nunca, y el barro tampoco. Los árboles entrelazan sus frondas tan densamente sobre el agua que la luz del sol llega fragmentada, y los crocoliscos y los múrlocs aguardan en los bajíos salobres donde el mar se encuentra con la ciénaga. En el sur, los dragones negros se reúnen en tal número que la gente lo llama sencillamente la Ciénaga de Fuego.\n\nJaina Valiente creó el primer hogar verdadero en esta tierra salvaje, cuando guio a su pueblo hasta aquí tras la batalla del Monte Hyjal para fundar Theramore en su isla rocosa. Las murallas de su ciudad relucen, pero también la encierran: más allá de los puestos de control dispersos en el camino hacia Los Baldíos, la ciénaga sigue tan salvaje como siempre, y su guarnición ha menguado por deserciones silenciosas que nadie sabe explicar.\n\nFue también aquí donde la paz entre la Horda y la Alianza se rompió para siempre. El almirante Daelin Valiente lanzó la flota de Kul Tiras contra la Horda en la ciénaga, y la escaramuza que siguió acabó con su muerte, convirtiendo la tregua en abierta enemistad.\n\nEl Poblado Murohelecho se alza donde los ogros Quebrantarrocas abrieron sus puertas a la Horda. Más allá, el camino hacia Los Baldíos está vacío y se va deteriorando, sin más vigilancia que la de los raptores y las arañas que siempre han sido dueños de este terreno.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "La arena ocupa el lugar donde antes se alzaba una jungla. Antes de que el mundo se quebrara, Tanaris era verde, y el Imperio Gurubashi la reclamaba como territorio.",
		full = "La arena ocupa el lugar donde antes se alzaba una jungla. Antes de que el mundo se quebrara, Tanaris era verde, y el Imperio Gurubashi la reclamaba como territorio. Cuando el Gran Diluvio desgarró la tierra, la jungla murió y lo que quedó se coció hasta convertirse en dunas y piedra. Una tribu de trols quedó atrapada aquí cuando las aguas se retiraron, y a lo largo de los largos años que siguieron, sus cuerpos y sus costumbres se plegaron al desierto hasta que dejaron de ser los trols que habían sido y se convirtieron en trols de arena, los Furiarena, un pueblo forjado por la tierra que los atrapó.\n\nLos goblins del Cártel Bonvapor eligieron este yermo para su comercio y fundaron Gadgetzan y Puerto Bonvapor porque el desierto es lo más parecido a su patria hundida donde Kalimdor les permite asentarse. Los muelles de Bonvapor se extienden hacia las islas lejanas, pero los goblins guardan sus barcos para sí mismos y no están dispuestos a llevar a ninguna otra raza al otro lado del agua.\n\nBajo las dunas y las montañas del sur, los túneles se extienden durante kilómetros, en su mayoría sin cartografiar, y quienes descienden no siempre regresan para contar lo que encontraron.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "El otoño lleva diez mil años adueñado de Azshara, con sus árboles ardiendo en naranjas y rojos sobre acantilados que caen hacia el coral donde aún yace una ciudad.",
		full = "El otoño lleva diez mil años adueñado de Azshara, con sus árboles ardiendo en naranjas y rojos sobre acantilados que caen hacia el coral donde aún yace una ciudad. Azshara fue antaño la mayor metrópolis que jamás levantaron los elfos de la noche, y cuando llegó la Guerra de los Ancestros, la mayor parte se hundió en el mar. Unos pocos edificios en ruinas aún se aferran al acantilado, contemplando sus propias ruinas bajo el agua.\n\nMucho después, cuando Illidan Tempestira huyó hacia el norte desde el Monte Hyjal con sus nagas, mur'guls y sátiros a remolque, arrasó la costa de Azshara y destrozó los puertos de los elfos de la noche para que nadie pudiera seguirlo hasta la Tumba de Sargeras. Maiev Shadowsong y sus Celadoras llegaron tras él, acabando con las criaturas enloquecidas que dejaba a su paso.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Frondavil",
		short = "Los árboles de Frondavil no tanto crecen como se pudren.",
		full = "Los árboles de Frondavil no tanto crecen como se pudren. Su corteza supura un icor enfermizo, sus hojas cuelgan negras y rizadas, y la fauna que vive bajo ellos surge retorcida y hambrienta por la corrupción del suelo.\n\nLa podredumbre no fue un accidente de la naturaleza. Mientras la Legión Ardiente avanzaba hacia el Monte Hyjal, Archimonde ordenó quebrar el bosque para debilitar a los elfos de la noche que custodiaban la montaña, y el señor del terror Tichondrius cumplió esa orden con una reliquia de brujo de terrible poder, el Cráneo de Gul'dan. La tierra respondió muriendo de dentro hacia fuera: los ancianos se volvieron podridos y violentos, las bestias mutaron y la propia tierra quedó envenenada.\n\nFue aquí donde Illidan Tempestira tomó la decisión que marcó el resto de su vida. Tras oír que el cráneo podía volverse contra la misma corrupción que había causado, Illidan entró solo en Frondavil, abatió a Tichondrius y se quedó con la reliquia. No la entregó después. Su hambre de magia resultó más fuerte que la prudencia, y por usar el propio poder de la Legión fue desterrado por su propio hermano, Malfurion.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Cráter de Un'Goro",
		short = "El Cráter de Un'Goro yace aislado entre tres desiertos, una herida verde hundida en el sur de Kalimdor, donde el mundo se olvida de ser yermo.",
		full = "El Cráter de Un'Goro yace aislado entre tres desiertos, una herida verde hundida en el sur de Kalimdor, donde el mundo se olvida de ser yermo. Dinosaurios más antiguos que la memoria se mueven por su jungla, algunos crecidos hasta tamaños que ningún ser vivo debería alcanzar, y elementales de tierra y fuego caminan tranquilos entre ellos. En las crestas de arriba se alzan pilones que nadie ha sabido explicar jamás.\n\nDurante la guerra del Mar de Dunas, los elfos de la noche se vieron obligados a retroceder a través de este cráter hasta el borde del desierto de Tanaris, y allí se quebró el avance qiraji. Algo en el propio Un'Goro no permitió que los invasores se apoderaran de la tierra, aunque nadie ha dicho qué.\n\nUna expedición dirigida por Williden y Hol'anyee Marshal intentó en su día establecer un asentamiento aquí, pero la ferocidad del cráter resultó superior a aquello para lo que se habían preparado. Sus campamentos fueron arrasados, y los supervivientes huyeron a terrenos más altos, donde resistieron en lo que hoy se llama el Refugio de Marshal.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Claro de la Luna",
		short = "El Claro de la Luna yace acunado en un anillo de montañas, un valle oculto donde el bosque nunca ha conocido la corrupción.",
		full = "El Claro de la Luna yace acunado en un anillo de montañas, un valle oculto donde el bosque nunca ha conocido la corrupción. En su corazón reposa el Lago Elune'ara, llamado así por la propia diosa, y en el pueblo de Amparo de la Noche, a su orilla, tauren y elfos de la noche caminan juntos sin disputas, unidos por una reverencia compartida hacia la naturaleza que los Guardianes del Claro de la Luna no permitirán que se rompa.\n\nFue a este valle adonde acudió Malfurion Tempestira en los días de la Guerra de los Ancestros, cuando los elfos de la noche estaban al borde de la ruina frente a la Legión. Malfurion sabía que su pueblo no podría vencer solo, y condujo a Tyrande Susurravientos y a su hermano Illidan a la quietud sagrada del Claro de la Luna para suplicar a Cenarius su ayuda. El semidiós respondió, y después de que el Gran Diluvio remodelara el mundo, los guardianes de la arboleda y las dríades que se habían refugiado aquí partieron hacia él. El propio Cenarius nunca se marchó, y el Claro de la Luna se convirtió en el suelo más sagrado del culto druídico.\n\nBajo sus innumerables túmulos duermen los santuarios de druidas del pasado, y bajo las aguas del Elune'ara duerme el semidiós Omen, antaño amado de Elune, con un sueño inquieto.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "El desierto se encuentra en el extremo suroccidental de Kalimdor, un yermo de roca quebrada y arena al que se llega por el amplio camino que sale de Un'Goro.",
		full = "El desierto se encuentra en el extremo suroccidental de Kalimdor, un yermo de roca quebrada y arena al que se llega por el amplio camino que sale de Un'Goro. Bajo su superficie yace el vestigio del imperio aqir, Ahn'Qiraj, cuyo templo central sellaron los elfos de la noche en un intento de impedir que algo terrible despertara. Las ruinas esparcidas por Silithus y las colmenas de silítidos que ahora acribillan la arena son prueba suficiente de que el sello no resistió.\n\nHace mucho tiempo, los propios qiraji fueron empujados tras el Muro del Escarabajo y encerrados allí tras la guerra del Mar de Dunas. Sus sirvientes, los silítidos, quedaron libres, y a lo largo de los siglos se multiplicaron y se extendieron por todo el sur de Kalimdor, hasta que los elfos de la noche juzgaron que la amenaza era demasiado grande para seguir limitándose a vigilarla y optaron por reabrir las Puertas de Ahn'Qiraj para terminar lo que el Muro solo había aplazado.\n\nEl Círculo Cenarion vigila desde el Fuerte Cenarion, siguiendo el rastro de los enjambres de silítidos y sopesando si son un peligro demasiado grande para que un solo pueblo lo afronte en solitario.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Cuna del Invierno",
		short = "La nieve se extiende intacta por Cuna del Invierno, y su belleza permanece inalterada incluso allí donde los demonios han invadido las regiones del sur. Antaño fue el hogar de muchos miembros del Vuelo Azul, entre ellos Haleh, consorte de Malygos.",
		full = "La nieve se extiende intacta por Cuna del Invierno, y su belleza permanece inalterada incluso allí donde los demonios han invadido las regiones del sur. Antaño fue el hogar de muchos miembros del Vuelo Azul, entre ellos Haleh, consorte de Malygos.\n\nHace diez mil años, los Altonato levantaron aquí la ciudad de Kel'Theril, tras robar el cristal de Zin-Malor de un templo de Eldarath. No pudieron resistirse a poner a prueba su poder, y cuando se hizo añicos, la maldición que desató los devoró. El Gran Diluvio terminó lo que el cristal había empezado, y Kel'Theril quedó en ruinas. Sus muertos nunca se marcharon. Más tarde, altos elfos llegaron desde Quel'Thalas en busca de los fragmentos del cristal, y la misma locura se apoderó de ellos. Ahora sus fantasmas recorren las ruinas junto a aquellos a los que vinieron a estudiar.\n\nLos goblins ocupan Vista Eterna en el corazón del valle, y los elfos de la noche aún mantienen aquí su propia vigilancia, custodiando una patria más antigua que cualquiera de ellos.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Ciudad de Ventormenta",
		short = "Ventormenta se alzó en piedra blanca después de que la Horda orca la incendiara, reconstruida por el Gremio de Canteros bajo el joven rey Varian.",
		full = "Ventormenta se alzó en piedra blanca después de que la Horda orca la incendiara, reconstruida por el Gremio de Canteros bajo el joven rey Varian. Pero cuando las arcas de la corona se vaciaron por las deudas de guerra y la nobleza negó al gremio sus salarios, la protesta del maestro del gremio Edwin VanCleef recibió como respuesta la disolución del gremio. Siguieron disturbios, y en el caos murió la reina Tiffin Wrynn. La ira de Varian empujó a los canteros al exilio en los Páramos de Poniente, donde se convirtieron en la Hermandad Defias, mientras que tras el trono una consejera llamada Katrana Prestor volvía en silencio al rey contra el gremio para sus propios fines.\n\nDesde entonces, el rey Varian ha desaparecido en circunstancias sospechosas y, por insistencia de lady Prestor, la corona pasó a su joven hijo, el príncipe Anduin, para preservar el orden en el reino. El alto señor Bolvar Fordragon ejerce de regente de Ventormenta y comandante de sus fuerzas, mientras lady Prestor lo asesora sobre el uso de los recursos del reino, sin que nadie sospeche de ella ni la desafíe dentro del castillo.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Orgrimmar se alzó en los años posteriores al Monte Hyjal, cuando el Jefe de Guerra Thrall condujo a su pueblo a una costa desolada de Kalimdor.",
		full = "Orgrimmar se alzó en los años posteriores al Monte Hyjal, cuando el Jefe de Guerra Thrall condujo a su pueblo a una costa desolada de Kalimdor. Llamó a la tierra Durotar en honor a su padre, y a la ciudad que levantó allí la llamó Orgrimmar, por Orgrim Martillo Maldito, el amigo y mentor que lo había formado. Se construyó deprisa, pero no a la ligera: murallas robustas, puertas enormes y altas torres, con las montañas a su espalda talladas para formar parte de la propia fortaleza, de modo que la tierra montara guardia sobre la ciudad.\n\nLa Horda que la construyó no era la Horda que antaño había arrasado el mundo. Rota la maldición demoníaca, el pueblo de Thrall pasó de la conquista a la supervivencia, y Orgrimmar la levantaron tanto otros como los orcos: goblins, tauren y trols Lanza Negra trabajaron junto a ellos, y el mok'nathal Rexxar echó una mano en la obra. Centauros, arpías, truenagartos, kóbolds y jabaespines pusieron a prueba a la joven ciudad en sus primeros años, pero resistió, y se convirtió en hogar no solo de orcos, sino también de trols, tauren y, con el tiempo, de los Renegados, recién acogidos en la Horda.\n\nEl propio viento no es ningún amigo aquí: los vientos cortantes barren los valles con fuerza suficiente para arrancar los tejados de los edificios levantados sin cuidado.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Forjaz",
		short = "Forjaz es la capital de los enanos, excavada en las profundidades de la Montaña Forjaz, en el norte de Dun Morogh, hogar ancestral de los enanos y una de las ciudades más antiguas de Azeroth.",
		full = "Forjaz es la capital de los enanos, excavada en las profundidades de la Montaña Forjaz, en el norte de Dun Morogh, hogar ancestral de los enanos y una de las ciudades más antiguas de Azeroth. Es la capital de Khaz Modan, gobernada por el rey Magni Barbabronce, del clan Barbabronce.\n\nVasta ciudad subterránea de artesanos, exploradores, mineros y guerreros, famosa por su industria y como centro comercial de la Alianza, Forjaz es a partes iguales fortaleza y capital, testimonio de la fuerza y la resistencia de los enanos. La ciudad consta de anillos concéntricos, con niveles más pequeños a mayor profundidad, que irradian todos desde la Gran Fundición que se halla en su centro y a la que debe su nombre. Está llena de pequeños pasadizos, tiendas excavadas en los muros de roca y salas cavernosas. El ambiente es bullicioso, ruidoso e industrial, pero acogedor; el fuego ruge en los hogares de las posadas y las tiendas, y se oyen muchas risas y jolgorio enanos. A diferencia de Ventormenta y Darnassus, la ciudad es una enorme caverna excavada en la tierra por los propios enanos; tanto el techo como el suelo son de piedra dura.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Cima del Trueno",
		short = "Cima del Trueno se alza sobre cuatro mesetas azotadas por el viento por encima de las praderas de Mulgore, y solo se llega a ella por ascensores de cuerda y madera de factura tauren o por largos puentes tendidos entre las alturas.",
		full = "Cima del Trueno se alza sobre cuatro mesetas azotadas por el viento por encima de las praderas de Mulgore, y solo se llega a ella por ascensores de cuerda y madera de factura tauren o por largos puentes tendidos entre las alturas. Tiendas, casas comunales y tótems pintados coronan cada cumbre. Durante generaciones, los tauren vagaron como un pueblo nómada, acosados sin descanso por los centauros que recorrían Kalimdor. Fue Cairne Pezuña de Sangre, jefe de la tribu Pezuña de Sangre, quien puso fin a aquel exilio. Cuando el Jefe de Guerra Thrall y su Nueva Horda llegaron a Mulgore durante la Tercera Guerra, su fuerza se sumó a la de Cairne y juntos derrotaron a los centauros y ganaron por fin las praderas para los tauren. Sobre las mesetas, Cairne levantó un refugio abierto a todas las tribus dispersas, y con el tiempo esas tribus se sometieron a su mando como un solo pueblo, discrepando a veces sobre el camino a seguir, pero nunca sobre su sabiduría para guiarlas.\n\nLas cimas aún llevan el peso de aquella fundación en sus alturas y sus puentes, en las tiendas de las tribus reunidas bajo el techo de un solo jefe.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Los elfos de la noche construyeron Darnassus después de la Tercera Guerra, cuando su larga inmortalidad les falló. Muchos no pudieron soportar el repentino peso del envejecimiento y la fragilidad.",
		full = "Los elfos de la noche construyeron Darnassus después de la Tercera Guerra, cuando su larga inmortalidad les falló. Muchos no pudieron soportar el repentino peso del envejecimiento y la fragilidad. Un grupo de druidas afligidos decidió plantar un nuevo Árbol del Mundo para restaurar su vínculo con el mundo eterno. Con Malfurion Tempestira desaparecido, Fandral Corzocelada asumió el manto de archidruida y dirigió la empresa. El árbol que alzaron, Teldrassil, creció frente a la costa hasta que su copa atravesó las nubes, y entre sus ramas los elfos de la noche fundaron su ciudad como testimonio de la supervivencia de su pueblo.\n\nDarnassus está abierta al cielo, a diferencia de las ciudades cerradas y amuralladas de los humanos y los enanos. Está construida alrededor de un amplio lago, cuyas orillas se unen mediante elegantes puentes, y sus senderos están alfombrados de hojas caídas. El Templo de la Luna se alza sobre los árboles como sede de la suma sacerdotisa Tyrande Susurravientos y sus Hermanas de Elune, junto a la columnata del Salón de la Justicia, donde las Centinelas montan guardia. La ciudad sigue siendo aquello para lo que fue construida: un refugio tranquilo y un monumento a un pueblo que aprende a vivir con la mortalidad.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Entrañas",
		short = "Mucho antes de que los Renegados la hicieran suya, Entrañas ya tenía un nombre y un propósito. Muy por debajo del palacio de Lordaeron se extendían las antiguas criptas de sus muertos reales, sus mazmorras, sus cloacas.",
		full = "Mucho antes de que los Renegados la hicieran suya, Entrañas ya tenía un nombre y un propósito. Muy por debajo del palacio de Lordaeron se extendían las antiguas criptas de sus muertos reales, sus mazmorras, sus cloacas. Estaba destinada solo a prisioneros y cadáveres, pero los más pobres del pueblo de Lordaeron se apiñaban igualmente en la oscuridad, y las batidas de los guardias para desalojarlos nunca surtían efecto.\n\nCuando el dominio del Rey Exánime sobre sus creaciones se debilitó, Sylvanas Brisaveloz se separó de la Plaga junto con los no-muertos que habían conservado la razón, y se volvió contra Arthas, el príncipe caído que la había convertido en lo que era. Lo atrajo a una trampa en el reino en ruinas; él escapó con la ayuda de Kel'Thuzad y huyó al norte para convertirse él mismo en el Rey Exánime. Sylvanas y sus seguidores, dueños del campo, se llamaron a sí mismos los Renegados y reclamaron las criptas bajo la capital destrozada, terminando el bastión que la Plaga había empezado.\n\nLo que se alza hoy es un laberinto construido para la defensa: ríos de lodo venenoso recorren cada avenida, y el aire está cargado de vapores que los vivos apenas soportan respirar. Para los Renegados es un refugio en un mundo que todavía les da caza.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

